import numpy as np


def max_shift(z):
    z = np.asarray(z, dtype=float)
    return z - z.max()

import numpy as np


def max_shift(z):
    z = np.asarray(z, dtype=float)
    return z - z.max(axis=0, keepdims=True)

import numpy as np


def max_shift(z):
    z = np.asarray(z, dtype=float)
    return z - z.min(axis=1, keepdims=True)

import numpy as np


def log_sum_exp_rows(z):
    z = np.asarray(z, dtype=float)
    return np.log(np.exp(z).sum(axis=1))
